import * as THREE from '../three.module.js';
// Procedural microtexture: no additional network assets or runtime downloads.
export function detailMaterial(material,kind){material.onBeforeCompile=shader=>{shader.vertexShader='varying vec3 surfacePosition;\n'+shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nsurfacePosition=position;');shader.fragmentShader='varying vec3 surfacePosition;\n'+shader.fragmentShader;const pattern=kind==='leather'?'sin(surfacePosition.x*1800.0)*sin(surfacePosition.y*1600.0)*sin(surfacePosition.z*1750.0)':kind==='fabric'?'sin(surfacePosition.x*420.0)*sin(surfacePosition.y*550.0)':'sin(surfacePosition.x*87.0+sin(surfacePosition.z*63.0))*sin(surfacePosition.z*153.0)';shader.fragmentShader=shader.fragmentShader.replace('#include <color_fragment>',`#include <color_fragment>\nfloat microDetail=${pattern};diffuseColor.rgb*=0.94+0.06*microDetail;`).replace('#include <roughnessmap_fragment>','#include <roughnessmap_fragment>\nroughnessFactor=clamp(roughnessFactor+microDetail*0.055,0.1,1.0);');};material.customProgramCacheKey=()=>kind+'-detail-v1';return material;}
export function addBallStitching(ball){const mat=new THREE.MeshStandardMaterial({color:'#d7bf97',roughness:.85}),geometry=new THREE.SphereGeometry(1,5,4),mesh=new THREE.InstancedMesh(geometry,mat,144),dummy=new THREE.Object3D();for(let row=0;row<6;row++)for(let i=0;i<24;i++){const a=i/24*Math.PI*2+(row%2)*.018,z=(row-2.5)*.0011,r=Math.sqrt(.0365**2-z*z);dummy.position.set(Math.cos(a)*r,Math.sin(a)*r,z);dummy.scale.set(.001,.00045,.00045);dummy.rotation.z=a+.65;dummy.updateMatrix();mesh.setMatrixAt(row*24+i,dummy.matrix);}ball.add(mesh);detailMaterial(ball.material,'leather');}
export function addNearGrass(scene){const geometry=new THREE.BufferGeometry();const blades=[];for(let i=0;i<5;i++){const a=i*2.4,x=Math.sin(a)*.022,z=Math.cos(a)*.022;blades.push(x-.005,0,z,x+.005,0,z,x+.01,.035+i*.013,z+.009);}geometry.setAttribute('position',new THREE.Float32BufferAttribute(blades,3));geometry.computeVertexNormals();const material=new THREE.MeshStandardMaterial({color:'#456345',roughness:1,side:THREE.DoubleSide}),grass=new THREE.InstancedMesh(geometry,material,2200),dummy=new THREE.Object3D();let seed=73;const random=()=>{seed=(seed*16807)%2147483647;return seed/2147483647;};for(let i=0;i<2200;i++){const side=random()<.5?-1:1;dummy.position.set(side*(1.8+random()*8),.003,-12+random()*17);dummy.rotation.y=random()*6.28;dummy.scale.setScalar(.4+random()*.7);dummy.updateMatrix();grass.setMatrixAt(i,dummy.matrix);grass.setColorAt(i,new THREE.Color().setHSL(.23+random()*.035,.25+random()*.18,.28+random()*.12));}grass.receiveShadow=true;grass.castShadow=false;scene.add(grass);return grass;}
